 52	async function renderPlan(app, repo, slug) {
 53	  app.innerHTML = '<p class="loading">Loading plan\u2026</p>';
 54	  try {
 55	    var result = await API.getPlanDocument(repo, slug);
 56	    var html = marked.parse(result.content);
 57	    app.innerHTML =
 58	      breadcrumb().projects().project(repo, slug).leaf('Plan').html() +
