107	function buildPipelineTrack(overviewEntry) {
108	  if (!overviewEntry || !overviewEntry.pipeline_stages || !overviewEntry.pipeline_stages.length) {
109	    return '—';
110	  }
111	  var badges = overviewEntry.pipeline_stages.map(function (stage) {
112	    var abbrev = STAGE_ABBREV[stage.type] || stage.type.slice(0, 3).toUpperCase();
113	    var statusClass = 'stage-pending';
114	    if (stage.status === 'in-progress') statusClass = 'stage-in-progress';
115	    else if (stage.status === 'pass')        statusClass = 'stage-pass';
116	    else if (stage.status === 'fail')        statusClass = 'stage-fail';
117	    var tooltip = escapeHtml(stage.type) + ' — ' + escapeHtml(stage.agent);
118	    if (stage.rework_count > 0) tooltip += ' (rework: ' + stage.rework_count + ')';
119	    var reworkBadge = stage.rework_count > 0
120	      ? '<span class="rework-indicator" title="Rework count: ' + stage.rework_count + '">' + stage.rework_count + '</span>'
121	      : '';
122	    return '<span class="stage-badge ' + statusClass + '" title="' + tooltip + '">' +
123	      escapeHtml(abbrev) +
124	      reworkBadge +
125	    '</span>';
126	  }).join('');
127	  return '<div class="pipeline-track">' + badges + '</div>';
128	}
