131	  var badges = '';
132	  if (isActive) {
133	    badges += '<span class="badge badge-in-progress">Running</span>';
134	  }
135	  if (item && item.is_dry_run) {
136	    badges += '<span class="badge badge-dry-run">Dry Run</span>';
137	  }
138	  return badges;
139	}
