426	/* ----------------------------------------------------------
427	   4c-iii. State Snapshot & Diff Helpers
428	   Pure functions — no DOM access, JSON-serializable outputs.
429	   Used by WP-003 polling to decide patch vs. full re-render.
430	   ---------------------------------------------------------- */
431	
432	/**
433	 * Extract a comparable state snapshot from API response objects.
434	 *
435	 * @param {object} project      - Response from API.getProject()
436	 * @param {Array|null} overviewResult - Response from API.getWorkPackageOverview() (may be null)
437	 * @returns {{
438	 *   status: string,
439	 *   last_updated: string,
440	 *   synthesis_generated: boolean,
441	 *   wpStatuses: Object.<string, { status: string, pipelineStages: Array }>,
442	 *   health: null | { work_packages_needing_reset: number }
443	 * }}
444	 */
445	function _snapshotProjectState(project, overviewResult) {
446	  var meta = (project && project.meta) || {};
447	  var wps  = (project && project.work_packages) || [];
448	
449	  // Build per-WP status map
450	  var wpStatuses = {};

451	  wps.forEach(function (wp) {
452	    if (!wp || !wp.work_package_id) return;
453	    wpStatuses[wp.work_package_id] = {
454	      status: wp.status || '',
455	      pipelineStages: [],
456	    };
457	  });
458	
459	  // Enrich with pipeline stage data from overview
460	  if (Array.isArray(overviewResult)) {
461	    overviewResult.forEach(function (entry) {
462	      if (!entry || !entry.work_package_id) return;
463	      var id = entry.work_package_id;
464	      var stages = Array.isArray(entry.pipeline_stages)
465	        ? entry.pipeline_stages.map(function (s) {
466	            return {
467	              type:         s.type        || '',
468	              status:       s.status      || '',
469	              agent:        s.agent       || '',
470	              rework_count: s.rework_count || 0,
471	            };
472	          })
473	        : [];
474	      if (wpStatuses[id]) {
475	        wpStatuses[id].pipelineStages = stages;
476	      } else {
477	        // Overview entry present without a matching WP in the main list.
478	        wpStatuses[id] = { status: '', pipelineStages: stages };
479	      }
480	    });
481	  }
482	
483	  return {
484	    status:               meta.status              || '',
485	    last_updated:         meta.last_updated         || '',
486	    synthesis_generated:  !!(project && project.synthesis_generated),
487	    wpStatuses:           wpStatuses,
488	    health:               null,  // populated asynchronously via getProjectHealth()
489	  };
490	}
491	
492	/**
493	 * Compare two project-state snapshots and classify the difference.
494	 *
495	 * Structural changes (require full re-render):
496	 *   - The number of work packages differs between snapshots.
497	 *   - The project transitioned to COMPLETE or ARCHIVED status.
498	 *
499	 * Data-only changes (patchable in-place):
500	 *   - Status badge changed but is not a structural transition.
501	 *   - Any per-WP status or pipeline-stage changed.
502	 *   - synthesis_generated flipped.
503	 *   - health changed (including null → value transitions).
504	 *   - last_updated changed.
505	 *
506	 * @param {object} prev - Previous snapshot from _snapshotProjectState().
507	 * @param {object} next - Current  snapshot from _snapshotProjectState().
508	 * @returns {{ type: 'none'|'data'|'structural', changes: object }}
509	 */
510	function _diffProjectState(prev, next) {
511	  var changes = {};
512	  var changeType = 'none';
513	
514	  function markData(key, from, to) {
515	    changes[key] = { from: from, to: to };
516	    if (changeType === 'none') changeType = 'data';
517	  }
518	
519	  function markStructural(key, from, to) {
520	    changes[key] = { from: from, to: to };
521	    changeType = 'structural';
522	  }
523	
524	  // ── WP count ────────────────────────────────────────────────────────
525	  var prevIds = Object.keys(prev.wpStatuses || {});
526	  var nextIds = Object.keys(next.wpStatuses || {});
527	  if (prevIds.length !== nextIds.length) {
528	    markStructural('wpCount', prevIds.length, nextIds.length);
529	  }
530	
531	  // ── Project status ──────────────────────────────────────────────────
532	  if (prev.status !== next.status) {
533	    var isStructuralStatus = next.status === 'COMPLETE' || next.status === 'ARCHIVED';
534	    if (isStructuralStatus) {
535	      markStructural('status', prev.status, next.status);
536	    } else {
537	      markData('status', prev.status, next.status);
538	    }
539	  }
540	
541	  // ── Per-WP statuses and pipeline stages ─────────────────────────────
542	  nextIds.forEach(function (id) {
543	    var prevWp = (prev.wpStatuses || {})[id] || { status: '', pipelineStages: [] };
544	    var nextWp = (next.wpStatuses || {})[id] || { status: '', pipelineStages: [] };
545	
546	    if (prevWp.status !== nextWp.status) {
547	      markData('wp.' + id + '.status', prevWp.status, nextWp.status);
548	    }
549	
550	    // Compare pipeline stages as JSON strings (simple deep-equal for flat objects)
551	    var prevStagesStr = JSON.stringify(prevWp.pipelineStages || []);
552	    var nextStagesStr = JSON.stringify(nextWp.pipelineStages || []);
553	    if (prevStagesStr !== nextStagesStr) {
554	      markData('wp.' + id + '.pipelineStages', prevWp.pipelineStages, nextWp.pipelineStages);
555	    }
556	  });
557	
558	  // ── synthesis_generated ─────────────────────────────────────────────
559	  if (!!prev.synthesis_generated !== !!next.synthesis_generated) {
560	    markData('synthesis_generated', prev.synthesis_generated, next.synthesis_generated);
561	  }
562	
563	  // ── health ──────────────────────────────────────────────────────────
564	  // null-to-value (or any value change) is data-only
565	  var prevHealthStr = JSON.stringify(prev.health || null);
566	  var nextHealthStr = JSON.stringify(next.health || null);
567	  if (prevHealthStr !== nextHealthStr) {
568	    markData('health', prev.health, next.health);
569	  }
570	
571	  // ── last_updated ────────────────────────────────────────────────────
572	  if (prev.last_updated !== next.last_updated) {
573	    markData('last_updated', prev.last_updated, next.last_updated);
574	  }
575	
576	  return { type: changeType, changes: changes };
577	}
